import mongoose from 'mongoose';

const isProd = () => process.env.NODE_ENV === 'production';

// Cache the connection on globalThis so serverless runtimes (Vercel) reuse a
// single connection across warm invocations instead of reconnecting per request.
const cached = globalThis.__sabrMongo || (globalThis.__sabrMongo = { conn: null, promise: null });

// Bounded retry settings
const MAX_RETRIES = 3;
const RETRY_DELAY_MS = 2000;

function sleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

/**
 * Establish a single reusable MongoDB connection with bounded retries.
 *
 * Behavior:
 *  - No MONGODB_URI in production: throws (env.js should have already caught this).
 *  - No MONGODB_URI in dev: logs a warning and resolves null (in-memory fallback).
 *  - Connection failures are retried up to MAX_RETRIES times.
 *  - autoIndex is disabled in production (indexes should be synced via
 *    scripts/sync-indexes.mjs against Atlas).
 */
export async function connectDB() {
  const uri = process.env.MONGODB_URI;

  if (!uri) {
    if (isProd()) {
      throw new Error('MONGODB_URI is not set — cannot start in production without a database.');
    }
    console.warn('[db] MONGODB_URI not set — running with in-memory fallback data.');
    return null;
  }

  // Reuse existing active connection on warm instances
  if (cached.conn && mongoose.connection.readyState === 1) {
    return cached.conn;
  }

  // Globally disable autoIndex in production to prevent background index builds
  if (isProd()) {
    mongoose.set('autoIndex', false);
  }

  if (!cached.promise) {
    cached.promise = (async () => {
      let lastErr = null;

      for (let attempt = 1; attempt <= MAX_RETRIES; attempt++) {
        try {
          const conn = await mongoose.connect(uri, {
            bufferCommands: false, // In production, fail fast rather than buffering queries
            autoIndex: !isProd(),  // Disable autoIndex in production
            serverSelectionTimeoutMS: 5000,
            connectTimeoutMS: 10000,
          });
          console.log('[db] MongoDB connected.');
          return conn;
        } catch (err) {
          lastErr = err;
          // Never log the URI or any credentials — only the sanitized error message
          console.error(`[db] MongoDB connection attempt ${attempt}/${MAX_RETRIES} failed:`, err.message);
          if (attempt < MAX_RETRIES) {
            await sleep(RETRY_DELAY_MS * attempt);
          }
        }
      }

      // All retries exhausted
      throw lastErr;
    })();
  }

  try {
    cached.conn = await cached.promise;
  } catch (err) {
    cached.promise = null; // Allow future retry
    cached.conn = null;
    // In production, propagate the error so callers know DB is down
    if (isProd()) {
      throw err;
    }
    console.error('[db] MongoDB connection failed after retries:', err.message);
  }

  return cached.conn;
}

export default connectDB;

import { authService } from '../services/auth.service.js';
import { COOKIE_NAME, getCookieOptions, getClearCookieOptions } from '../utils/cookieOptions.js';

/**
 * Controller for Admin Authentication endpoints
 * References: Master Context §6.2, 05-auth.md §4; API.md §9, §10, §11
 */
class AuthController {
  /**
   * POST /api/auth/login
   * Authenticates admin with email & password, sets httpOnly cookie, returns sanitized admin profile
   */
  async login(req, res) {
    // Auth responses must never be cached (SECURITY.md §8 CACHE-04)
    res.setHeader('Cache-Control', 'no-store, no-cache, must-revalidate, proxy-revalidate');
    res.setHeader('Pragma', 'no-cache');
    res.setHeader('Expires', '0');

    try {
      const { email, password } = req.body;
      const result = await authService.loginAdmin(email, password);

      // Generic authentication failure response prevents account enumeration (05-auth.md §4)
      if (!result) {
        return res.status(401).json({
          success: false,
          message: 'Invalid email or password',
        });
      }

      const { admin, token } = result;
      const cookieOpts = getCookieOptions();

      // Set auth token as httpOnly, Secure, SameSite cookie
      if (typeof res.cookie === 'function') {
        res.cookie(COOKIE_NAME, token, cookieOpts);
      } else {
        // Fallback manual Set-Cookie header if running in raw Connect/Node http
        const cookieHeader = `${COOKIE_NAME}=${encodeURIComponent(token)}; Path=${cookieOpts.path}; Max-Age=${cookieOpts.maxAge / 1000}; HttpOnly${cookieOpts.secure ? '; Secure' : ''}; SameSite=${cookieOpts.sameSite}`;
        res.setHeader('Set-Cookie', cookieHeader);
      }

      // Return sanitized admin identity ONLY — NEVER return token or password hash (05-auth.md §4, §7)
      return res.status(200).json({
        success: true,
        message: 'Login successful',
        data: {
          admin,
          user: admin, // Included for frontend AuthContext compatibility
        },
      });
    } catch (err) {
      if (err.statusCode === 403) {
        return res.status(403).json({
          success: false,
          message: err.message || 'Account is disabled',
        });
      }

      console.error('[AuthController.login] Error:', err.message);
      return res.status(500).json({
        success: false,
        message: 'Internal server error during authentication',
      });
    }
  }

  /**
   * GET /api/auth/me
   * Validates active admin session and returns current admin identity
   */
  async getMe(req, res) {
    res.setHeader('Cache-Control', 'no-store, no-cache, must-revalidate, proxy-revalidate');
    res.setHeader('Pragma', 'no-cache');
    res.setHeader('Expires', '0');

    // req.admin populated by protect middleware
    return res.status(200).json({
      success: true,
      data: {
        admin: req.admin,
        user: req.admin,
      },
    });
  }

  /**
   * POST /api/auth/logout
   * Clears the authentication cookie and ends session
   */
  async logout(req, res) {
    res.setHeader('Cache-Control', 'no-store, no-cache, must-revalidate, proxy-revalidate');
    res.setHeader('Pragma', 'no-cache');
    res.setHeader('Expires', '0');

    const clearOpts = getClearCookieOptions();

    if (typeof res.clearCookie === 'function') {
      res.clearCookie(COOKIE_NAME, clearOpts);
    } else {
      const clearHeader = `${COOKIE_NAME}=; Path=${clearOpts.path}; Expires=Thu, 01 Jan 1970 00:00:00 GMT; HttpOnly${clearOpts.secure ? '; Secure' : ''}; SameSite=${clearOpts.sameSite}`;
      res.setHeader('Set-Cookie', clearHeader);
    }

    return res.status(200).json({
      success: true,
      message: 'Logged out successfully',
    });
  }
}

export const authController = new AuthController();

import {
  UPLOAD_FOLDERS,
  isCloudinaryConfigured,
  uploadImageBuffer,
} from '../services/cloudinary.service.js';

/**
 * POST /api/admin/uploads controller (Work 04).
 *
 * Route wiring (adminLimiter + protect) lives in apiHandler.js — this handler
 * only runs for an authenticated admin.
 *
 * Request : multipart/form-data, field "file" = one image, optional field
 *           "folder" = "projects" | "retail" (unknown values fall back to
 *           projects; the client can never choose an arbitrary folder).
 * Response: 201 { success: true, data: { images: [{ url, publicId }] } }
 *           — the same envelope shape the admin client already reads.
 *
 * Failure modes never fabricate a URL:
 *   400 no file / malformed  ·  413 too large  ·  415 wrong type
 *   503 Cloudinary not configured  ·  502 Cloudinary rejected the upload
 */
export const uploadController = {
  async uploadImage(req, res) {
    // Fail closed and say so plainly instead of returning a placeholder URL.
    if (!isCloudinaryConfigured()) {
      return res.status(503).json({
        success: false,
        message:
          'Image upload is not configured on the server (Cloudinary credentials missing).',
        code: 'UPLOAD_NOT_CONFIGURED',
      });
    }

    const image = req.uploadedImage;
    if (!image || !image.buffer) {
      return res.status(400).json({
        success: false,
        message: 'No image file received. Send a multipart/form-data "file" field.',
        code: 'UPLOAD_NO_FILE',
      });
    }

    const requestedFolder = String(req.body?.folder || req.body?.target || '').trim();
    const folder = Object.prototype.hasOwnProperty.call(UPLOAD_FOLDERS, requestedFolder)
      ? UPLOAD_FOLDERS[requestedFolder]
      : UPLOAD_FOLDERS.projects;

    try {
      const uploaded = await uploadImageBuffer(image.buffer, {
        folder,
        format: image.format,
      });

      return res.status(201).json({
        success: true,
        data: {
          images: [{ url: uploaded.url, publicId: uploaded.publicId }],
        },
      });
    } catch (err) {
      // Details stay server-side; the client gets a sanitized message.
      console.error('[Upload] Cloudinary upload failed:', err?.message || err);
      return res.status(502).json({
        success: false,
        message: 'Image upload failed. Please try again.',
        code: 'UPLOAD_FAILED',
      });
    }
  },
};

