/**
 * Detect the real image format from magic bytes. Returns null when the bytes
 * do not match an allowed image container — a renamed .exe lands here.
 */
export function detectImageType(buffer) {
  if (!Buffer.isBuffer(buffer) || buffer.length < 12) return null;

  // JPEG: FF D8 FF
  if (buffer.subarray(0, 3).equals(JPEG_MAGIC)) return 'jpg';

  // PNG: 89 50 4E 47 0D 0A 1A 0A
  if (buffer.subarray(0, 8).equals(PNG_MAGIC)) return 'png';

  // WEBP: 'RIFF' .... 'WEBP'
  if (
    buffer.toString('latin1', 0, 4) === 'RIFF' &&
    buffer.toString('latin1', 8, 12) === 'WEBP'
  ) {
    return 'webp';
  }

  // AVIF / animated AVIS: .... 'ftyp' 'avif'|'avis'
  if (buffer.toString('latin1', 4, 8) === 'ftyp') {
    const brand = buffer.toString('latin1', 8, 12);
    if (brand === 'avif' || brand === 'avis') return 'avif';
  }

  return null;
}

/** True when the declared MIME type is one we accept. */
export function isAllowedMimeType(mimeType) {
  return Object.prototype.hasOwnProperty.call(
    ALLOWED_MIME,
    String(mimeType || '').toLowerCase().trim()
  );
}

export const upload = multer({
  storage: multer.memoryStorage(),
  limits: {
    fileSize: MAX_UPLOAD_BYTES,
    files: 1,
    fields: 4, // only small text fields (e.g. folder target) are expected
    parts: 8,
  },
  fileFilter(req, file, cb) {
    if (!isAllowedMimeType(file.mimetype)) {
      // Named error so the route can answer 415 instead of a generic 400.
      const err = new Error(
        `Unsupported file type. Allowed: ${ALLOWED_IMAGE_EXTENSIONS.join(', ').toUpperCase()}.`
      );
      err.code = 'UPLOAD_UNSUPPORTED_TYPE';
      err.statusCode = 415;
      return cb(err, false);
    }
    cb(null, true);
  },
});

/**
 * Express-style middleware: parses one multipart image into req.file and
 * verifies its magic bytes. Responds directly with a sanitized JSON error so
 * the custom apiHandler router never has to interpret multer's errors.
 */
export function uploadImage(req, res, next) {
  upload.single(UPLOAD_FIELD)(req, res, (err) => {
    if (err) {
      if (err instanceof multer.MulterError) {
        if (err.code === 'LIMIT_FILE_SIZE') {
          return res.status(413).json({
            success: false,
            message: `Image is too large. Maximum size is ${MAX_UPLOAD_BYTES / (1024 * 1024)} MB.`,
            code: 'UPLOAD_TOO_LARGE',
          });
        }
        if (err.code === 'LIMIT_FILE_COUNT' || err.code === 'LIMIT_UNEXPECTED_FILE') {
          return res.status(400).json({
            success: false,
            message: 'Send exactly one image per upload request.',
            code: 'UPLOAD_TOO_MANY_FILES',
          });
        }
        return res.status(400).json({
          success: false,
          message: 'Malformed image upload request.',
          code: 'UPLOAD_BAD_REQUEST',
        });
      }
      if (err && err.code === 'UPLOAD_UNSUPPORTED_TYPE') {
        return res.status(err.statusCode || 415).json({
          success: false,
          message: err.message,
          code: err.code,
        });
      }
      console.error('[Upload] Unexpected multipart error:', err?.message || err);
      return res.status(400).json({
        success: false,
        message: 'Image upload could not be processed.',
        code: 'UPLOAD_BAD_REQUEST',
      });
    }

    const file = req.file;
    if (!file || !file.buffer) {
      return res.status(400).json({
        success: false,
        message: 'No image file received. Send a multipart/form-data "file" field.',
        code: 'UPLOAD_NO_FILE',
      });
    }

    const detected = detectImageType(file.buffer);
    if (!detected) {
      return res.status(415).json({
        success: false,
        message:
          'File contents are not a supported image (checked magic bytes, not the extension).',
        code: 'UPLOAD_INVALID_IMAGE',
      });
    }

    const declaredExt = ALLOWED_MIME[String(file.mimetype).toLowerCase()];
    if (declaredExt && declaredExt !== detected) {
      return res.status(415).json({
        success: false,
        message: 'File extension and actual image contents do not match.',
        code: 'UPLOAD_TYPE_MISMATCH',
      });
    }

    // Normalized, server-owned description of the image. The client filename
    // is intentionally discarded — nothing downstream reads it.
    req.uploadedImage = {
      buffer: file.buffer,
      size: file.size,
      mimeType: String(file.mimetype).toLowerCase(),
      format: detected,
    };
    return next();
  });
}

export default uploadImage;

import jwt from 'jsonwebtoken';
import bcrypt from 'bcrypt';
import mongoose from 'mongoose';
import { Admin, inMemoryAdmins } from '../models/admin.model.js';

function getJwtSecret() {
  const secret = process.env.JWT_SECRET;
  if (!secret) {
    if (process.env.NODE_ENV === 'production') {
      console.error('[FATAL] JWT_SECRET is missing in production. Process exiting.');
      process.exit(1);
    }
    throw new Error('JWT_SECRET is not configured');
  }
  if (process.env.NODE_ENV === 'production' && secret.length < 32) {
    console.error('[FATAL] JWT_SECRET must be at least 32 characters long in production. Process exiting.');
    process.exit(1);
  }
  return secret;
}

function getJwtExpiresIn() {
  return process.env.JWT_EXPIRES_IN || '24h';
}

/**
 * Idempotent first-run admin bootstrap from approved environment variables.
 * Uses ADMIN_EMAIL, ADMIN_PASSWORD, and ADMIN_NAME.
 */
export async function bootstrapAdmin() {
  const adminEmail = (process.env.ADMIN_EMAIL || '').toLowerCase().trim();
  const adminPassword = process.env.ADMIN_PASSWORD;
  const adminName = process.env.ADMIN_NAME || 'sabrstudio';

  if (!adminEmail || !adminPassword) {
    return null;
  }

  if (mongoose.connection && mongoose.connection.readyState === 1) {
    try {
      const count = await Admin.countDocuments({});
      if (count === 0) {
        const created = await Admin.create({
          name: adminName,
          email: adminEmail,
          password: adminPassword, // hashed by the schema pre-save hook
          role: 'admin',
          status: 'active',
        });
        console.log(`[AuthService] Idempotent bootstrap created initial admin: ${adminEmail}`);
        return created;
      }
    } catch (err) {
      console.error('[AuthService] Error during admin bootstrap:', err.message);
    }
  } else if (process.env.NODE_ENV !== 'production') {
    // Non-production in-memory fallback when Mongo is not connected
    if (inMemoryAdmins.length === 0) {
      const salt = await bcrypt.genSalt(10);
      const hash = await bcrypt.hash(adminPassword, salt);
      const devAdmin = {
        _id: 'admin-dev',
        id: 'admin-dev',
        name: adminName,
        email: adminEmail,
        password: hash,
        role: 'admin',
        status: 'active',
        lastLoginAt: null,
        createdAt: new Date(),
        updatedAt: new Date(),
      };
      inMemoryAdmins.push(devAdmin);
      return devAdmin;
    }
  }
  return null;
}

/**
 * Service to handle admin authentication operations
 * References: Master Context §6.2, 05-auth.md §4, §7, §8; ARCHITECTURE.md §10
 */
class AuthService {
  /**
   * Generates a signed JWT with admin ID and role only (no PII)
   * @param {Object} admin 
   * @returns {string} Signed JWT
   */
  generateToken(admin) {
    const adminId = admin._id ? admin._id.toString() : admin.id;
    const payload = {
      id: adminId,
      role: admin.role || 'admin',
    };

    return jwt.sign(payload, getJwtSecret(), {
      expiresIn: getJwtExpiresIn(),
    });
  }

  /**
   * Verifies and decodes a JWT token
   * @param {string} token 
   * @returns {Object} Decoded payload
   */
  verifyToken(token) {
    return jwt.verify(token, getJwtSecret());
  }

  /**
   * Authenticates admin by email and password
   * @param {string} email 
   * @param {string} password 
   * @returns {Promise<{ admin: Object, token: string } | null>}
   */
  async loginAdmin(email, password) {
    const normalizedEmail = (email || '').toLowerCase().trim();
    if (!normalizedEmail || !/^\S+@\S+\.\S+$/.test(normalizedEmail)) {
      return null;
    }
    const isProd = process.env.NODE_ENV === 'production';
    let admin = null;
    let passwordHash = null;

    // 1. Try Mongoose if connected
    if (mongoose.connection && mongoose.connection.readyState === 1) {
      try {
        admin = await Admin.findOne({ email: normalizedEmail }).select('+password');
        if (admin) {
          passwordHash = admin.password;
        }
      } catch (err) {
        console.error('[AuthService] Database error during lookup:', err.message);
      }
    }

    // 2. Fall back to in-memory store — NON-PRODUCTION ONLY.
    if (!admin && !isProd) {
      const memAdmin = inMemoryAdmins.find((a) => a.email.toLowerCase() === normalizedEmail);
      if (memAdmin) {
        admin = memAdmin;
        passwordHash = memAdmin.password;
      }
    }

    // 3. First-run bootstrap if collection is empty
    if (!admin && process.env.ADMIN_PASSWORD && password === process.env.ADMIN_PASSWORD) {
      const bootstrapEmail = (process.env.ADMIN_EMAIL || normalizedEmail).toLowerCase().trim();
      if (bootstrapEmail === normalizedEmail) {
        const bootstrapped = await bootstrapAdmin();
        if (bootstrapped) {
          admin = bootstrapped;
          passwordHash = bootstrapped.password;
        }
      }
    }

    // If no admin found, fail with null (controller sends generic 401)
    if (!admin || !passwordHash) {
      // Execute a dummy bcrypt compare to prevent timing side-channels
      await bcrypt.compare(password, '$2a$10$LuUvjIDZM37R/uP02T1CF.JWHBdhC9HdSmx.KpZoYyNvMGIKx6nvu');
      return null;
    }

    // Check password using bcrypt against the stored hash only
    const isMatch = await bcrypt.compare(password, passwordHash);
    if (!isMatch) {
      return null;
    }

    // Check if account is disabled (403 condition)
    if (admin.status === 'disabled') {
      const error = new Error('Account is disabled');
      error.statusCode = 403;
      throw error;
    }

    // Update lastLoginAt
    const now = new Date();
    if (typeof admin.save === 'function') {
      admin.lastLoginAt = now;
      await admin.save();
    } else {
      admin.lastLoginAt = now;
    }

    const adminId = admin._id ? admin._id.toString() : admin.id;
    const token = this.generateToken(admin);

    // Return sanitized admin identity (never password hash)
    const sanitizedAdmin = {
      id: adminId,
      name: admin.name,
      email: admin.email,
      role: admin.role,
      status: admin.status,
      lastLoginAt: admin.lastLoginAt,
    };

    return {
      admin: sanitizedAdmin,
      token,
    };
  }

  /**
   * Finds an admin by ID
   * @param {string} id 
   * @returns {Promise<Object | null>}
   */
  async getAdminById(id) {
    if (!id) return null;

    if (mongoose.connection && mongoose.connection.readyState === 1) {
      try {
        const admin = await Admin.findById(id);
        if (admin) {
          const adminId = admin._id.toString();
          return {
            id: adminId,
            name: admin.name,
            email: admin.email,
            role: admin.role,
            status: admin.status,
            lastLoginAt: admin.lastLoginAt,
          };
        }
      } catch (err) {
        console.error('[AuthService] Database error during getById:', err.message);
      }
    }

    // In-memory accounts are a NON-PRODUCTION convenience only. In production
    // the token's id must resolve to a real Mongo admin document (created by
    // the first-run bootstrap), so a forged/legacy id can never pass protect.
    if (process.env.NODE_ENV !== 'production') {
      const memAdmin = inMemoryAdmins.find(
        (a) => a.id === id || (a._id && a._id.toString() === id)
      );
      if (memAdmin) {
        return {
          id: memAdmin.id || memAdmin._id,
          name: memAdmin.name,
          email: memAdmin.email,
          role: memAdmin.role,
          status: memAdmin.status,
          lastLoginAt: memAdmin.lastLoginAt,
        };
      }
    }

    return null;
  }
}

export const authService = new AuthService();

import crypto from 'crypto';

/**
 * Cloudinary media service — the ONLY module allowed to talk to Cloudinary.
 *
 * Contract (Work 04 — real image upload):
 *  - Credentials stay server-side and are read from CLOUDINARY_CLOUD_NAME /
 *    CLOUDINARY_API_KEY / CLOUDINARY_API_SECRET (approved env inventory).
 *  - If they are missing we NEVER fabricate a URL; callers must return 503.
 *  - Every upload lands in one of the fixed folders below. Client-supplied
 *    folder names, filenames and paths are never used — public IDs are random.
 *  - Deletion is best-effort: a cleanup failure must never break the request
 *    that triggered it, so every helper here resolves instead of throwing.
 */

// Fixed destination folders. Keys are the public values the admin client may send.
export const UPLOAD_FOLDERS = Object.freeze({
  projects: 'sabrstudio/projects',
  retail: 'sabrstudio/retail',
});

export const DEFAULT_UPLOAD_FOLDER = UPLOAD_FOLDERS.projects;

/** True only when all three Cloudinary credentials are present (values never logged). */
export function isCloudinaryConfigured() {
  return Boolean(
    String(process.env.CLOUDINARY_CLOUD_NAME || '').trim() &&
      String(process.env.CLOUDINARY_API_KEY || '').trim() &&
      String(process.env.CLOUDINARY_API_SECRET || '').trim()
  );
}

/** Maps a client target ('projects' | 'retail') to a fixed server folder. */
export function resolveFolder(target) {
  const key = String(target || '').trim().toLowerCase();
  return UPLOAD_FOLDERS[key] || DEFAULT_UPLOAD_FOLDER;
}

/** Random, non-guessable public ID. The client filename is deliberately ignored. */
export function randomPublicId() {
  return `${Date.now().toString(36)}-${crypto.randomBytes(10).toString('hex')}`;
}

async function getClient() {
  const { v2: cloudinary } = await import('cloudinary');
  cloudinary.config({
    cloud_name: process.env.CLOUDINARY_CLOUD_NAME,
    api_key: process.env.CLOUDINARY_API_KEY,
    api_secret: process.env.CLOUDINARY_API_SECRET,
    secure: true,
  });
  return cloudinary;
}

/**
 * Upload an in-memory buffer to Cloudinary with upload_stream (no filesystem:
 * Vercel's is read-only).
 * @returns {Promise<{url:string, publicId:string, width:number, height:number, format:string, bytes:number}>}
 */
export async function uploadImageBuffer(buffer, options = {}) {
  const folder = options.folder || DEFAULT_UPLOAD_FOLDER;
  const format = options.format;
  const cloudinary = await getClient();

  return new Promise((resolve, reject) => {
    const stream = cloudinary.uploader.upload_stream(
      {
        folder,
        public_id: randomPublicId(),
        resource_type: 'image',
        overwrite: false,
        unique_filename: false,
        use_filename: false,
        invalidate: true,
        ...(format ? { format } : {}),
      },
      (error, result) => {
        if (error) return reject(error);
        if (!result || !result.secure_url || !result.public_id) {
          return reject(new Error('Cloudinary response did not include a secure_url/public_id.'));
        }
        resolve({
          url: result.secure_url,
          publicId: result.public_id,
          width: result.width ?? null,
          height: result.height ?? null,
          format: result.format ?? null,
          bytes: result.bytes ?? null,
        });
      }
    );

    stream.on('error', reject);
    stream.end(Buffer.isBuffer(buffer) ? buffer : Buffer.from(buffer));
  });
}

/**
 * Delete one Cloudinary asset. Best-effort: resolves true/false, never throws.
 */
export async function deleteAsset(publicId) {
  const id = String(publicId || '').trim();
  if (!id || !isCloudinaryConfigured()) return false;
  try {
    const cloudinary = await getClient();
    const result = await cloudinary.uploader.destroy(id, {
      resource_type: 'image',
      invalidate: true,
    });
    return result?.result === 'ok' || result?.result === 'not found';
  } catch (err) {
    // Cleanup must never break the caller (replace/delete request).
    console.warn('[Cloudinary] Asset cleanup failed for one public_id:', err?.message || err);
    return false;
  }
}

/**
 * Delete many Cloudinary assets, ignoring blanks and duplicates.
 * Best-effort: always resolves with a small summary, never rejects.
 */
export async function deleteAssets(publicIds) {
  const ids = Array.from(
    new Set(
      (Array.isArray(publicIds) ? publicIds : [publicIds])
        .map((id) => String(id || '').trim())
        .filter(Boolean)
    )
  );
  if (!ids.length) return { deleted: 0, failed: 0 };
  if (!isCloudinaryConfigured()) return { deleted: 0, failed: ids.length };

  const outcomes = await Promise.allSettled(ids.map((id) => deleteAsset(id)));
  return {
    deleted: outcomes.filter((o) => o.status === 'fulfilled' && o.value).length,
    failed: outcomes.filter((o) => o.status !== 'fulfilled' || !o.value).length,
  };
}

/**
 * Collect Cloudinary public IDs stored on a Project/Retail document so a
 * replace or delete can clean the old assets up. Tolerates legacy documents
 * (plain string images, missing publicId) by simply skipping them.
 */
export function collectPublicIds(doc) {
  if (!doc) return [];
  const ids = [];
  const push = (value) => {
    const id = typeof value === 'string' ? value : value?.publicId;
    const clean = String(id || '').trim();
    if (clean) ids.push(clean);
  };
  if (Array.isArray(doc.images)) doc.images.forEach(push);
  push(doc.imagePublicId);
  if (Array.isArray(doc.gallery)) doc.gallery.forEach((g) => push({ publicId: g?.publicId }));
  return ids;
}

export default {
  UPLOAD_FOLDERS,
  DEFAULT_UPLOAD_FOLDER,
  isCloudinaryConfigured,
  resolveFolder,
  randomPublicId,
  uploadImageBuffer,
  deleteAsset,
  deleteAssets,
  collectPublicIds,
};

