const RESET_TTL_MS = 15 * 60 * 1000; // 15 minutes
const RESET_RESEND_COOLDOWN_MS = 60 * 1000; // 60 seconds
const RESET_MAX_ATTEMPTS = 5;
const hashResetToken = (token) => crypto.createHash('sha256').update(String(token)).digest('hex');
const normalizeEmail = (v) => String(v || '').toLowerCase().trim();
const isValidEmail = (v) => /^\S+@\S+\.\S+$/.test(v);

// Phone-login OTP policy.
const OTP_TTL_MS = 5 * 60 * 1000; // 5 minutes
const OTP_RESEND_COOLDOWN_MS = 60 * 1000; // 60 seconds
const OTP_MAX_ATTEMPTS = 5;
const OTP_LENGTH = 6;
const hashOtp = (code) => crypto.createHash('sha256').update(String(code)).digest('hex');
const normalizePhone = (v) => String(v || '').replace(/[^\d+]/g, '').trim();
const isValidPhone = (v) => /^\+?\d{10,15}$/.test(v);
const genOtp = () => String(crypto.randomInt(0, 1000000)).padStart(OTP_LENGTH, '0');

const inMemoryCustomers = [];
const memKey = (c) => String(c.email || '').toLowerCase();

function sanitize(c) {
  if (!c) return null;
  const id = c._id ? String(c._id) : c.id;
  return {
    id, _id: id,
    name: c.name, email: c.email,
    phone: c.phone || '',
    avatar: c.avatar || '',
    role: 'customer',
    status: c.status || 'active',
    googleId: c.googleId || null,
    addresses: c.addresses || [],
    lastLoginAt: c.lastLoginAt || null,
  };
}

class CustomerService {
  generateToken(c) {
    const id = c._id ? String(c._id) : c.id;
    return jwt.sign({ id, role: 'customer', kind: 'customer' }, getJwtSecret(), { expiresIn: getJwtExpiresIn() });
  }
  verifyToken(t) { return jwt.verify(t, getJwtSecret()); }

  async findById(id) {
    if (!id) return null;
    if (mongoose.connection?.readyState === 1) {
      try {
        const doc = await Customer.findById(id);
        if (doc) return doc;
      } catch {
        /* ignore lookup errors */
      }
    }
    return inMemoryCustomers.find((c) => String(c.id) === String(id) || String(c._id) === String(id)) || null;
  }

  async register({ name, email, password, phone }) {
    const cleanEmail = String(email || '').toLowerCase().trim();
    const cleanName = String(name || '').trim();
    if (!cleanName || cleanName.length < 2) { const e = new Error('Please enter your full name.'); e.statusCode = 400; throw e; }
    if (!/^\S+@\S+\.\S+$/.test(cleanEmail)) { const e = new Error('Please enter a valid email address.'); e.statusCode = 400; throw e; }
    if (!password || String(password).length < 6) { const e = new Error('Password must be at least 6 characters.'); e.statusCode = 400; throw e; }
    const connected = mongoose.connection?.readyState === 1;
    if (connected) {
      const exists = await Customer.findOne({ email: cleanEmail });
      if (exists) { const e = new Error('An account with this email already exists. Please log in.'); e.statusCode = 409; throw e; }
      const doc = await Customer.create({ name: cleanName, email: cleanEmail, password, phone: String(phone || '') });
      doc.lastLoginAt = new Date(); await doc.save();
      return { customer: sanitize(doc.toObject()), token: this.generateToken(doc) };
    }
    if (inMemoryCustomers.some((c) => memKey(c) === cleanEmail)) { const e = new Error('An account with this email already exists. Please log in.'); e.statusCode = 409; throw e; }
    const hash = await bcrypt.hash(String(password), 10);
    const rec = { id: `cust-${Date.now()}`, _id: `cust-${Date.now()}`, name: cleanName, email: cleanEmail, password: hash, phone: String(phone || ''), addresses: [], status: 'active', lastLoginAt: new Date() };
    inMemoryCustomers.unshift(rec);
    return { customer: sanitize(rec), token: this.generateToken(rec) };
  }

  async login(email, password) {
    const cleanEmail = String(email || '').toLowerCase().trim();
    let doc = null; let hash = null;
    if (mongoose.connection?.readyState === 1) {
      try { doc = await Customer.findOne({ email: cleanEmail }).select('+password'); if (doc) hash = doc.password; } catch { /* ignore */ }
    }
    if (!doc) {
      const mem = inMemoryCustomers.find((c) => memKey(c) === cleanEmail);
      if (mem) { doc = mem; hash = mem.password; }
    }
    if (!doc || !hash) {
      await bcrypt.compare(String(password || ''), '$2a$10$LuUvjIDZM37R/uP02T1CF.JWHBdhC9HdSmx.KpZoYyNvMGIKx6nvu');
      return null;
    }
    const ok = await bcrypt.compare(String(password || ''), hash);
    if (!ok) return null;
    if (doc.status === 'disabled') { const e = new Error('Account is disabled'); e.statusCode = 403; throw e; }
    doc.lastLoginAt = new Date();
    if (typeof doc.save === 'function') { try { await doc.save(); } catch { /* ignore */ } }
    const plain = typeof doc.toObject === 'function' ? doc.toObject() : doc;
    return { customer: sanitize(plain), token: this.generateToken(doc) };
  }

  async googleLogin({ googleId, email, name, avatar }) {
    const cleanEmail = String(email || '').toLowerCase().trim();
    if (!cleanEmail) { const e = new Error('Google account email is required.'); e.statusCode = 400; throw e; }
    const connected = mongoose.connection?.readyState === 1;
    if (connected) {
      let doc = googleId ? await Customer.findOne({ googleId }) : null;
      if (!doc) doc = await Customer.findOne({ email: cleanEmail });
      if (!doc) {
        doc = await Customer.create({ name: String(name || cleanEmail.split('@')[0]), email: cleanEmail, googleId: googleId || null, avatar: avatar || '' });
      } else {
        if (googleId && !doc.googleId) doc.googleId = googleId;
        if (avatar && !doc.avatar) doc.avatar = avatar;
        doc.lastLoginAt = new Date(); await doc.save();
      }
      return { customer: sanitize(doc.toObject()), token: this.generateToken(doc) };
    }
    let mem = (googleId && inMemoryCustomers.find((c) => c.googleId === googleId)) || inMemoryCustomers.find((c) => memKey(c) === cleanEmail);
    if (!mem) {
      mem = { id: `cust-${Date.now()}`, _id: `cust-${Date.now()}`, name: String(name || cleanEmail.split('@')[0]), email: cleanEmail, password: null, googleId: googleId || null, avatar: avatar || '', phone: '', addresses: [], status: 'active', lastLoginAt: new Date() };
      inMemoryCustomers.unshift(mem);
    } else { mem.lastLoginAt = new Date(); }
    return { customer: sanitize(mem), token: this.generateToken(mem) };
  }

  async _findCustomerByEmail(cleanEmail) {
    if (mongoose.connection?.readyState === 1) {
      try { return await Customer.findOne({ email: cleanEmail }); } catch { return null; }
    }
    return inMemoryCustomers.find((c) => memKey(c) === cleanEmail) || null;
  }

  async _sendResetEmail(email, name, token) {
    try {
      const { sendEnquiryEmail } = await import('./emailjs.service.js');
      await sendEnquiryEmail({
        name: name || 'Sabr Studio customer',
        phone: '',
        email,
        projectType: 'Password reset request',
        message: `Your Sabr Studio password-reset code is: ${token}\n\nThis code expires in 15 minutes and can be used once. If you did not request this, you can safely ignore this email.`,
      }, {});
      return true;
    } catch (err) {
      console.error('[CustomerService] reset email failed:', err?.code || err?.message);
      return false;
    }
  }

  /**
   * Enumeration-safe: always resolves {sent:true} whether or not the account
   * exists, and never reveals delivery status to the caller.
   */
  async requestPasswordReset(email) {
    const cleanEmail = normalizeEmail(email);
    if (!isValidEmail(cleanEmail)) return { sent: true };
    const doc = await this._findCustomerByEmail(cleanEmail);
    if (!doc) return { sent: true };
    const now = Date.now();
    const lastSent = doc.passwordReset?.lastSentAt ? new Date(doc.passwordReset.lastSentAt).getTime() : 0;
    if (lastSent && now - lastSent < RESET_RESEND_COOLDOWN_MS) return { sent: true }; // cooldown, silent
    const token = crypto.randomBytes(32).toString('hex');
    const patch = {
      passwordReset: {
        tokenHash: hashResetToken(token),
        expiresAt: new Date(now + RESET_TTL_MS),
        attempts: 0,
        lastSentAt: new Date(now),
        usedAt: null,
      },
    };
    if (mongoose.connection?.readyState === 1 && typeof doc.save === 'function') {
      doc.passwordReset = patch.passwordReset;
      try { await doc.save(); } catch { /* ignore */ }
    } else {
      doc.passwordReset = patch.passwordReset;
    }
    await this._sendResetEmail(cleanEmail, doc.name, token);
    return { sent: true };
  }

  async resetPassword(email, token, newPassword) {
    const cleanEmail = normalizeEmail(email);
    const raw = String(token || '').trim();
    if (!isValidEmail(cleanEmail) || !raw) { const e = new Error('Invalid or expired reset code.'); e.statusCode = 400; throw e; }
    if (!newPassword || String(newPassword).length < 6) { const e = new Error('Password must be at least 6 characters.'); e.statusCode = 400; throw e; }
    const doc = await this._findCustomerByEmail(cleanEmail);
    const pr = doc?.passwordReset;
    const invalid = () => { const e = new Error('Invalid or expired reset code.'); e.statusCode = 400; throw e; };
    if (!doc || !pr || !pr.tokenHash || !pr.expiresAt) invalid();
    if (pr.usedAt) invalid();
    if (new Date(pr.expiresAt).getTime() < Date.now()) invalid();
    if ((pr.attempts || 0) >= RESET_MAX_ATTEMPTS) invalid();
    if (hashResetToken(raw) !== pr.tokenHash) {
      pr.attempts = (pr.attempts || 0) + 1;
      if (typeof doc.save === 'function') { try { await doc.save(); } catch { /* ignore */ } }
      invalid();
    }
    // Valid: rotate password, invalidate token (single-use).
    doc.password = String(newPassword);
    pr.tokenHash = null; pr.usedAt = new Date(); pr.attempts = 0; pr.expiresAt = null;
    if (mongoose.connection?.readyState === 1 && typeof doc.save === 'function') {
      await doc.save(); // pre-save hook hashes the password
    } else {
      doc.password = await bcrypt.hash(String(newPassword), 10);
    }
    return { customer: sanitize(typeof doc.toObject === 'function' ? doc.toObject() : doc) };
  }

  /**
   * Update own profile only (id comes from the verified JWT, never the body).
   * Email changes are sensitive: require the current password (re-auth) and
   * enforce uniqueness + normalization.
   */
  async updateProfile(id, { name, phone, email, currentPassword }) {
    const connected = mongoose.connection?.readyState === 1;
    let doc = null;
    if (connected) { try { doc = await Customer.findById(id).select('+password'); } catch { doc = null; } }
    if (!doc) doc = inMemoryCustomers.find((c) => String(c.id) === String(id) || String(c._id) === String(id)) || null;
    if (!doc) { const e = new Error('Account not found.'); e.statusCode = 404; throw e; }

    const nextEmail = email !== undefined ? normalizeEmail(email) : undefined;
    if (nextEmail !== undefined && nextEmail !== normalizeEmail(doc.email)) {
      if (!isValidEmail(nextEmail)) { const e = new Error('Please enter a valid email address.'); e.statusCode = 400; throw e; }
      // Re-authentication for sensitive identity change.
      if (!doc.password) { const e = new Error('Email cannot be changed on a Google-only account.'); e.statusCode = 400; throw e; }
      const okPw = await bcrypt.compare(String(currentPassword || ''), doc.password);
      if (!okPw) { const e = new Error('Current password is incorrect.'); e.statusCode = 403; throw e; }
      const clash = await this._findCustomerByEmail(nextEmail);
      if (clash && String(clash._id || clash.id) !== String(doc._id || doc.id)) {
        const e = new Error('An account with this email already exists.'); e.statusCode = 409; throw e;
      }
      doc.email = nextEmail;
    }
    if (name !== undefined) {
      const cleanName = String(name).trim();
      if (cleanName.length < 2) { const e = new Error('Please enter your full name.'); e.statusCode = 400; throw e; }
      doc.name = cleanName;
    }
    if (phone !== undefined) doc.phone = String(phone).trim();

    if (connected && typeof doc.save === 'function') { await doc.save(); }
    return { customer: sanitize(typeof doc.toObject === 'function' ? doc.toObject() : doc) };
  }

  // ---- Phone OTP login --------------------------------------------------
  async _findCustomerByPhone(phone) {
    if (mongoose.connection?.readyState === 1) {
      try { return await Customer.findOne({ phone }); } catch { return null; }
    }
    return inMemoryCustomers.find((c) => String(c.phone || '') === phone) || null;
  }

  async _latestOtp(phone) {
    if (mongoose.connection?.readyState === 1) {
      try { return await OtpCode.findOne({ phone }).sort({ createdAt: -1 }); } catch { return null; }
    }
    return inMemoryOtps
      .filter((o) => o.phone === phone)
      .sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt))[0] || null;
  }

  async _saveOtp(record) {
    if (mongoose.connection?.readyState === 1) {
      await OtpCode.deleteMany({ phone: record.phone });
      return OtpCode.create(record);
    }
    for (let i = inMemoryOtps.length - 1; i >= 0; i--) if (inMemoryOtps[i].phone === record.phone) inMemoryOtps.splice(i, 1);
    inMemoryOtps.push({ ...record, createdAt: new Date() });
    return record;
  }

  async _deleteOtp(phone) {
    if (mongoose.connection?.readyState === 1) { try { await OtpCode.deleteMany({ phone }); } catch { /* ignore */ } return; }
    for (let i = inMemoryOtps.length - 1; i >= 0; i--) if (inMemoryOtps[i].phone === phone) inMemoryOtps.splice(i, 1);
  }

  /**
   * Request a phone OTP. Fails closed when no SMS provider is configured —
   * never generates, stores, or "sends" a code in that case.
   */
  async requestOtp(rawPhone) {
    const phone = normalizePhone(rawPhone);
    if (!isValidPhone(phone)) { const e = new Error('Please enter a valid phone number.'); e.statusCode = 400; throw e; }
    if (!isOtpProviderConfigured()) {
      const e = new Error('Phone OTP delivery is not configured on the server. Please log in with email instead.');
      e.statusCode = 503; e.code = 'OTP_PROVIDER_NOT_CONFIGURED'; throw e;
    }
    const latest = await this._latestOtp(phone);
    const lastSent = latest?.lastSentAt ? new Date(latest.lastSentAt).getTime() : 0;
    if (lastSent && Date.now() - lastSent < OTP_RESEND_COOLDOWN_MS) {
      const e = new Error('Please wait a moment before requesting another code.'); e.statusCode = 429; throw e;
    }
    const code = genOtp();
    await this._saveOtp({ phone, otpHash: hashOtp(code), expiresAt: new Date(Date.now() + OTP_TTL_MS), attempts: 0, lastSentAt: new Date(), verifiedAt: null });
    try {
      await sendOtpSms(phone, code);
    } catch (sendErr) {
      // A code that was never delivered must not be usable.
      await this._deleteOtp(phone);
      throw sendErr;
    }
    return { sent: true };
  }

  /**
   * Verify a phone OTP and, only on success, issue a session. Enforces expiry,
   * single-use, and attempt limits. A verified phone finds-or-creates the account.
   */
  async verifyOtp(rawPhone, rawCode) {
    const phone = normalizePhone(rawPhone);
    const code = String(rawCode || '').trim();
    if (!isValidPhone(phone) || !/^\d{4,8}$/.test(code)) { const e = new Error('Invalid phone number or code.'); e.statusCode = 400; throw e; }
    const rec = await this._latestOtp(phone);
    const invalid = (msg = 'Invalid or expired code.') => { const e = new Error(msg); e.statusCode = 400; throw e; };
    if (!rec || !rec.otpHash || !rec.expiresAt) invalid();
    if (rec.verifiedAt) invalid('This code has already been used. Request a new one.');
    if (new Date(rec.expiresAt).getTime() < Date.now()) invalid('This code has expired. Request a new one.');
    if ((rec.attempts || 0) >= OTP_MAX_ATTEMPTS) invalid('Too many incorrect attempts. Request a new code.');
    if (hashOtp(code) !== rec.otpHash) {
      rec.attempts = (rec.attempts || 0) + 1;
      if (typeof rec.save === 'function') { try { await rec.save(); } catch { /* ignore */ } }
      invalid();
    }
    // Valid: consume the code (single-use). Delete rather than null-out otpHash —
    // the field is schema-required, so a null save would silently fail and leave
    // the code replayable. Deletion guarantees single-use in both DB and memory.
    await this._deleteOtp(phone);

    let doc = await this._findCustomerByPhone(phone);
    if (!doc) {
      const placeholderEmail = `phone_${phone.replace(/\D/g, '')}@sabr.invalid`;
      doc = await this._findCustomerByEmail(placeholderEmail);
      if (!doc) {
        if (mongoose.connection?.readyState === 1) {
          doc = await Customer.create({ name: `Customer ${phone.slice(-4)}`, email: placeholderEmail, phone, password: null });
        } else {
          doc = { id: `cust-${Date.now()}`, _id: `cust-${Date.now()}`, name: `Customer ${phone.slice(-4)}`, email: placeholderEmail, phone, password: null, addresses: [], status: 'active', lastLoginAt: new Date() };
          inMemoryCustomers.unshift(doc);
        }
      }
    }
    if (doc.status === 'disabled') { const e = new Error('Account is disabled'); e.statusCode = 403; throw e; }
    doc.lastLoginAt = new Date();
    if (typeof doc.save === 'function') { try { await doc.save(); } catch { /* ignore */ } }
    const plain = typeof doc.toObject === 'function' ? doc.toObject() : doc;
    return { customer: sanitize(plain), token: this.generateToken(doc) };
  }
}

export const customerService = new CustomerService();
export const customerAuthService = customerService;

/**
 * EmailJS server-side delivery (REST: POST https://api.emailjs.com/api/v1.0/email/send).
 * Runs ONLY on the backend — private key never leaves the server.
 * Template params exactly match the shared EnquiryForm fields:
 *   name, phone, email, projectType, message
 */
const EMAILJS_SEND_URL = 'https://api.emailjs.com/api/v1.0/email/send';

const REQUIRED_VARS = [
  'EMAILJS_SERVICE_ID',
  'EMAILJS_TEMPLATE_ID',
  'EMAILJS_PUBLIC_KEY',
  'EMAILJS_PRIVATE_KEY',
];

function isPlaceholderLike(value) {
  if (!value) return true;
  const v = String(value).trim();
  if (!v) return true;
  return /^(xxxx|example|your-|test-|placeholder|change-?me|undefined|null)/i.test(v);
}

export function getEmailJsConfigStatus() {
  const missing = REQUIRED_VARS.filter((k) => !String(process.env[k] || '').trim());
  const placeholderLike = REQUIRED_VARS.filter(
    (k) => !missing.includes(k) && isPlaceholderLike(process.env[k])
  );
  const invalid = [...missing, ...placeholderLike];
  return {
    configured: invalid.length === 0,
    missing,
    placeholderLike,
    invalid,
  };
}

function classifyEmailJsError(status, bodyText) {
  const text = String(bodyText || '');
  if (/non-browser environments|enable.*security|access.*disabled/i.test(text)) {
    return { code: 'EMAILJS_AUTH_FAILED', statusCode: 502 };
  }
  if (
    status === 401 || status === 403 ||
    /invalid.*(key|token|access|user_id)|unauthorized|forbidden|access denied/i.test(text)
  ) {
    return { code: 'EMAILJS_AUTH_FAILED', statusCode: 502 };
  }
  if (status === 400 && /public key is invalid/i.test(text)) {
    return { code: 'EMAILJS_AUTH_FAILED', statusCode: 502 };
  }
  if (status === 404 || /service.*not found|template.*not found|invalid.*(service|template)/i.test(text)) {
    return { code: 'EMAILJS_INVALID_SERVICE_OR_TEMPLATE', statusCode: 502 };
  }
  if (status === 429 || /rate limit|too many/i.test(text)) {
    return { code: 'EMAILJS_RATE_LIMITED', statusCode: 503 };
  }
  if (status >= 500) {
    return { code: 'EMAILJS_API_FAILURE', statusCode: 502 };
  }
  return { code: 'EMAILJS_SEND_FAILED', statusCode: 502 };
}

/**
 * Send one enquiry notification via EmailJS REST.
 * Resolves { ok:true } ONLY when EmailJS returns HTTP 200 with body "OK".
 * Rejects with an operational error carrying { emailCode, statusCode, missing }
 * for: config missing (EMAILJS_CONFIG_MISSING), auth, invalid service/template,
 * rate-limit, network/timeout, generic API failure. Never includes secrets.
 */
export async function sendEnquiryEmail({ name, phone, email, projectType, message }, options = {}) {
  const status = getEmailJsConfigStatus();
  if (!status.configured) {
    const err = new Error(
      `Email service is not configured (missing: ${status.invalid.join(', ')}).`
    );
    err.code = 'EMAILJS_CONFIG_MISSING';
    err.statusCode = 503;
    err.missing = status.invalid;
    throw err;
  }

  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), 15000);

  // EmailJS REST API requires an Origin header; without it, API access is rejected with
  // 403 Forbidden ("API access from non-browser environments is currently disabled").
  const callerOrigin = options.origin;
  const requestOrigin =
    callerOrigin ||
    process.env.EMAILJS_ORIGIN ||
    process.env.APP_URL ||
    (process.env.VERCEL_URL ? `https://${process.env.VERCEL_URL}` : null) ||
    'https://sabrstudio.in';

  const cleanName = String(name || '').trim();
  const cleanProjectType = String(projectType || '').trim();
  const cleanEmail = String(email || '').trim();
  const cleanPhone = String(phone || '').trim();
  const cleanMessage = String(message || '').trim();

  // Subject requirement: "New Enquiry from {{name}} — {{projectType}}"
  const subjectLine = cleanProjectType
    ? `New Enquiry from ${cleanName || 'Prospective Client'} — ${cleanProjectType}`
    : `New Enquiry from ${cleanName || 'Prospective Client'}`;

  const templateParams = {
    name: cleanName,
    phone: cleanPhone,
    email: cleanEmail,
    projectType: cleanProjectType,
    message: cleanMessage,
    subject: subjectLine,
    reply_to: cleanEmail || '',
  };

  let res;
  let bodyText = '';
  try {
    res = await fetch(EMAILJS_SEND_URL, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Origin': requestOrigin,
        'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36',
      },
      signal: controller.signal,
      body: JSON.stringify({
        service_id: process.env.EMAILJS_SERVICE_ID,
        template_id: process.env.EMAILJS_TEMPLATE_ID,
        user_id: process.env.EMAILJS_PUBLIC_KEY,
        accessToken: process.env.EMAILJS_PRIVATE_KEY,
        template_params: templateParams,
      }),
    });
    bodyText = await res.text().catch(() => '');
  } catch (networkErr) {
    const err = new Error(
      networkErr?.name === 'AbortError'
        ? 'Email service timed out. Please try again.'
        : 'Email service is temporarily unreachable. Please try again.'
    );
    err.code = networkErr?.name === 'AbortError' ? 'EMAILJS_TIMEOUT' : 'EMAILJS_NETWORK_FAILURE';
    err.statusCode = 503;
    err.cause = networkErr;
    throw err;
  } finally {
    clearTimeout(timeout);
  }

  const ok = res.ok && bodyText.trim() === 'OK';
  if (!ok) {
    const { code, statusCode } = classifyEmailJsError(res.status, bodyText);
    const safeDetail = bodyText.slice(0, 300).replace(/[\r\n]+/g, ' ');
    // Safe server-side log: status + EmailJS message only, never keys/secrets.
    console.error(
      `[EmailJS] send failed: code=${code} http=${res.status} detail=${safeDetail || '(empty response)'}`
    );
    const err = new Error('Failed to deliver enquiry email. Please try again.');
    err.code = code;
    err.statusCode = statusCode;
    err.emailjsStatus = res.status;
    err.emailjsDetail = safeDetail;
    throw err;
  }

  return { ok: true };
}

import { Enquiry, inMemoryEnquiries } from '../models/enquiry.model.js';
import { fallbackEnquiries } from '../utils/fallbackStorage.js';
import { sendEnquiryEmail } from './emailjs.service.js';

const SERVICE_SLUG_MAP = {
  'residential-interiors': 'Residential Interiors',
  'commercial-interiors': 'Commercial Interiors',
  'space-planning': 'Space Planning',
  'furniture-layout': 'Furniture Layout',
  '3d-visualization': '3D Visualization',
  'material-colour-consultation': 'Material & Colour Consultation',
};

export const enquiryService = {
  /**
   * Create public enquiry — STRICT delivery-verified flow:
   *   1. Save enquiry to DB (Mongo, else persistent fallback).
   *   2. Send EmailJS notification server-side and VERIFY the result.
   *   3. DB success + email success  → resolve { record, emailSent:true }.
   *   4. DB success + email failure  → preserve record, mark emailStatus
   *      'failed', and THROW (so the controller returns success:false —
   *      never a false success). DB failure → throw.
   * References: DATABASE.md §2.3; prompts/06-features.md §4.6
   * C4: email is optional (collected when provided).
   * C5: projectType is captured from the inquiry form's required select.
   */
  async createEnquiry(data) {
    const rawProjectType = String(data.projectType || '').trim();
    const formattedProjectType = SERVICE_SLUG_MAP[rawProjectType] || rawProjectType;

    const enquiryData = {
      name: String(data.name || '').trim(),
      email: String(data.email || '').trim(),
      phone: String(data.phone || '').trim(),
      projectType: formattedProjectType,
      message: String(data.message || '').trim(),
      source: data.source || data.sourceRoute || '/contact',
      sourceRoute: data.sourceRoute || data.source || '/contact',
      status: 'new',
      emailStatus: 'pending',
      emailError: '',
    };

    let createdRecord;
    let storage = 'mongo';
    const isMongoConnected = Enquiry.db?.readyState === 1;

    if (isMongoConnected) {
      const doc = await Enquiry.create(enquiryData);
      createdRecord = doc.toObject();
    } else {
      // Use persistent fallback storage
      storage = 'fallback';
      createdRecord = fallbackEnquiries.add(enquiryData);
    }

    const recordId = createdRecord._id || createdRecord.id;

    const persistEmailStatus = async (patch) => {
      try {
        if (storage === 'mongo' && Enquiry.db?.readyState === 1) {
          await Enquiry.updateOne({ _id: recordId }, { $set: patch });
          Object.assign(createdRecord, patch);
        } else if (storage === 'fallback') {
          const updated = fallbackEnquiries.update(recordId, patch);
          if (updated) createdRecord = updated;
          else Object.assign(createdRecord, patch);
        } else {
          Object.assign(createdRecord, patch);
        }
      } catch (persistErr) {
        console.error(`[Enquiry] email-status persist failed for ${recordId}:`, persistErr.message);
      }
    };

    // Email notification is REQUIRED for success — verify the actual result.
    try {
      await sendEnquiryEmail(
        {
          name: createdRecord.name,
          phone: createdRecord.phone,
          email: createdRecord.email || '',
          projectType: createdRecord.projectType || '',
          message: createdRecord.message || '',
        },
        {
          origin: data.origin,
        }
      );
      await persistEmailStatus({ emailStatus: 'sent', emailError: '' });
      return { record: createdRecord, emailSent: true };
    } catch (emailErr) {
      // Preserve the enquiry, record the failure (safe message only — no secrets).
      const safeCode = emailErr.code || 'EMAILJS_SEND_FAILED';
      await persistEmailStatus({ emailStatus: 'failed', emailError: safeCode });
      // Safe server log: which config is missing / which class failed — no values.
      if (safeCode === 'EMAILJS_CONFIG_MISSING') {
        console.error(
          `[Enquiry] email not sent (enquiry ${recordId} preserved): missing EmailJS config: ${(emailErr.missing || []).join(', ') || 'unknown'}`
        );
      } else {
        console.error(
          `[Enquiry] email not sent (enquiry ${recordId} preserved): ${safeCode}`
        );
      }
      // Re-throw so the controller returns success:false (never false success).
      throw emailErr;
    }
  },

  /**
   * Get all enquiries (strictly admin-only)
   * References: prompts/06-features.md §5.5
   */
  async getAdminEnquiries() {
    const isMongoConnected = Enquiry.db?.readyState === 1;
    if (isMongoConnected) {
      const items = await Enquiry.find().sort({ createdAt: -1 }).lean();
      return items.map((doc) => ({
        ...doc,
        id: doc.id || doc._id?.toString(),
      }));
    }
    // Fallback to persistent storage, then in-memory
    const fallbackData = fallbackEnquiries.findAll();
    if (fallbackData.length > 0) {
      return fallbackData;
    }
    return [...inMemoryEnquiries];
  },

  /**
   * Get enquiry by ID (strictly admin-only)
   */
  async getAdminEnquiryById(id) {
    const isMongoConnected = Enquiry.db?.readyState === 1;
    if (isMongoConnected) {
      return await Enquiry.findOne({
        $or: [{ _id: id.match(/^[0-9a-fA-F]{24}$/) ? id : null }, { id }],
      }).lean();
    }
    // Check fallback storage first
    const fallbackEnquiry = fallbackEnquiries.findOne({ _id: id, id: id });
    if (fallbackEnquiry) {
      return fallbackEnquiry;
    }
    return inMemoryEnquiries.find((e) => e.id === id || e._id === id) || null;
  },

  /**
   * Update enquiry status (admin only)
   * Only allows modifying status ('new', 'contacted', 'pending').
   * Never mutates user's original message, email, or phone.
   */
  async updateEnquiryStatus(id, newStatus) {
    const validStatuses = ['new', 'contacted', 'pending'];
    if (!validStatuses.includes(newStatus)) {
      throw new Error(`Invalid enquiry status: ${newStatus}`);
    }

    const isMongoConnected = Enquiry.db?.readyState === 1;
    if (isMongoConnected) {
      return await Enquiry.findOneAndUpdate(
        { $or: [{ _id: id.match(/^[0-9a-fA-F]{24}$/) ? id : null }, { id }] },
        { $set: { status: newStatus } },
        { new: true, runValidators: true }
      ).lean();
    }

    // Update in fallback storage
    const enq = fallbackEnquiries.findOne({ _id: id, id: id });
    if (!enq) {
      // Check in-memory as last resort
      const memEnq = inMemoryEnquiries.find((e) => e.id === id || e._id === id);
      if (!memEnq) return null;
      memEnq.status = newStatus;
      memEnq.updatedAt = new Date();
      return memEnq;
    }

    fallbackEnquiries.update(id, { status: newStatus, updatedAt: new Date() });
    return fallbackEnquiries.findOne({ _id: id, id: id });
  },

  /**
   * Delete enquiry (admin only)
   */
  async deleteEnquiry(id) {
    const isMongoConnected = Enquiry.db?.readyState === 1;
    if (isMongoConnected) {
      const doc = await Enquiry.findOneAndDelete({
        $or: [{ _id: id.match(/^[0-9a-fA-F]{24}$/) ? id : null }, { id }],
      }).lean();
      return !!doc;
    }

    // Delete from fallback storage
    const deleted = fallbackEnquiries.delete(id);
    if (deleted) return true;

    // Try in-memory as last resort
    const initialLength = inMemoryEnquiries.length;
    const filtered = inMemoryEnquiries.filter((e) => e.id !== id && e._id !== id);
    if (filtered.length < initialLength) {
      inMemoryEnquiries.length = 0;
      inMemoryEnquiries.push(...filtered);
      return true;
    }
    return false;
  },
};

/**
 * SMS delivery for phone-login OTPs. Runs ONLY on the backend; provider
 * credentials never leave the server. If no provider is configured we FAIL
 * CLOSED — we never simulate a send or pretend verification succeeded.
 *
 * Supported provider: Twilio Programmable SMS (REST). Configure with:
 *   TWILIO_ACCOUNT_SID, TWILIO_AUTH_TOKEN, TWILIO_FROM_NUMBER
 */
const REQUIRED_VARS = ['TWILIO_ACCOUNT_SID', 'TWILIO_AUTH_TOKEN', 'TWILIO_FROM_NUMBER'];

export function isOtpProviderConfigured() {
  return REQUIRED_VARS.every((k) => String(process.env[k] || '').trim().length > 0);
}

function otpProviderError() {
  const e = new Error('Phone OTP delivery is not configured on the server. Please use email login, or contact support.');
  e.code = 'OTP_PROVIDER_NOT_CONFIGURED';
  e.statusCode = 503;
  return e;
}

/**
 * Send a 6-digit code via the configured SMS provider.
 * Resolves true only on a real provider 2xx. Throws an operational error otherwise.
 */
export async function sendOtpSms(phone, code) {
  if (!isOtpProviderConfigured()) throw otpProviderError();

  const sid = process.env.TWILIO_ACCOUNT_SID;
  const token = process.env.TWILIO_AUTH_TOKEN;
  const from = process.env.TWILIO_FROM_NUMBER;
  const url = `https://api.twilio.com/2010-04-01/Accounts/${encodeURIComponent(sid)}/Messages.json`;
  const auth = Buffer.from(`${sid}:${token}`).toString('base64');

  const controller = new AbortController();
  const t = setTimeout(() => controller.abort(), 15000);
  let res;
  try {
    res = await fetch(url, {
      method: 'POST',
      signal: controller.signal,
      headers: {
        Authorization: `Basic ${auth}`,
        'Content-Type': 'application/x-www-form-urlencoded',
      },
      body: new URLSearchParams({
        To: phone,
        From: from,
        Body: `Your Sabr Studio login code is ${code}. It expires in 5 minutes and can be used once.`,
      }),
    });
  } catch (networkErr) {
    const e = new Error('Could not reach the SMS provider. Please try again.');
    e.code = networkErr?.name === 'AbortError' ? 'OTP_TIMEOUT' : 'OTP_NETWORK_FAILURE';
    e.statusCode = 502;
    throw e;
  } finally {
    clearTimeout(t);
  }

  if (!res.ok) {
    // Log status only — never the code or provider credentials.
    console.error(`[OTP] SMS send failed: http=${res.status}`);
    const e = new Error('SMS provider could not deliver the code. Please try again.');
    e.code = 'OTP_SEND_FAILED';
    e.statusCode = 502;
    throw e;
  }
  return true;
}

/**
 * Safe startup environment validation — production entry only (backend/server.js).
 *
 * - Names missing keys; NEVER prints values.
 * - Placeholder-looking values (example/changeme/xxxx/test-/...) count as missing.
 * - Production FAILS FAST only on JWT_SECRET (admin/customer login would throw
 *   'JWT_SECRET is not configured' on first use anyway — this surfaces it at boot).
 * - Everything else warns: MONGODB_URI (app boots + /api 503s by design),
 *   CORS_ORIGIN, ADMIN_PASSWORD (first-run lockout risk), APP_URL (EmailJS Origin).
 * - Optional integrations warn per feature group only when PARTIALLY configured.
 * - Dev/test never fail: local work boots without Atlas or third-party keys.
 */
const PLACEHOLDER_RE = /^(xxxx|example|your-|test-|placeholder|change-?me|undefined|null|<.*>)\s*$/i;

function isBlank(v) {
  return !String(v || '').trim();
}
function isPlaceholder(v) {
  const s = String(v || '').trim();
  if (!s) return true;
  return PLACEHOLDER_RE.test(s) || /^(1234|password|secret)$/i.test(s);
}
function isValidHttpUrl(v) {
  try {
    const u = new URL(String(v).trim());
    return u.protocol === 'http:' || u.protocol === 'https:';
  } catch {
    return false;
  }
}

function groupStatus(keys) {
  const missing = keys.filter((k) => isPlaceholder(process.env[k]));
  return { configured: missing.length === 0, missing };
}

export function checkEnv() {
  const isProd = process.env.NODE_ENV === 'production';
  const warnings = [];
  const fatals = [];

  // --- Fatal in production only ---
  if (isProd && isPlaceholder(process.env.JWT_SECRET)) {
    fatals.push('JWT_SECRET is missing or placeholder-like (admin/customer login cannot work).');
  }

  // --- Recommended in production (warn) ---
  if (isProd) {
    if (isBlank(process.env.MONGODB_URI)) {
      warnings.push('MONGODB_URI is not set — app boots but /api/* returns 503 DB_UNAVAILABLE (in-memory fallback is dev-only).');
    }
    if (isBlank(process.env.CORS_ORIGIN)) {
      warnings.push('CORS_ORIGIN is not set — cross-origin browsers (e.g. Vercel preview) will be blocked; same-domain Hostinger SPA is unaffected.');
    }
    if (isBlank(process.env.ADMIN_PASSWORD)) {
      warnings.push('ADMIN_PASSWORD is not set — first-run production bootstrap cannot create the initial admin (lockout risk on an empty admins collection).');
    }
    if (isBlank(process.env.APP_URL) && isBlank(process.env.EMAILJS_ORIGIN)) {
      warnings.push('APP_URL/EMAILJS_ORIGIN are not set — server-side EmailJS calls fall back to the Vercel origin and may be rejected with 403.');
    }
    const expiry = String(process.env.JWT_EXPIRES_IN || '24h').trim();
    if (!/^\d+[smhd]$/.test(expiry)) {
      warnings.push(`JWT_EXPIRES_IN=${expiry} does not look like a jsonwebtoken duration (e.g. 24h, 7d, 30d).`);
    }
    for (const key of ['APP_URL', 'EMAILJS_ORIGIN']) {
      const v = process.env[key];
      if (!isBlank(v) && !isValidHttpUrl(v)) {
        warnings.push(`${key} is not a valid http(s) URL.`);
      }
    }
    const origins = String(process.env.CORS_ORIGIN || '').split(',').map((o) => o.trim()).filter(Boolean);
    for (const o of origins) {
      if (!isValidHttpUrl(o)) warnings.push(`CORS_ORIGIN entry is not a valid http(s) URL: origin hidden (value not printed).`);
    }
  }

  // --- Optional integrations: warn only when partially configured ---
  const groups = {
    'Razorpay checkout (RAZORPAY_KEY_ID, RAZORPAY_KEY_SECRET)': ['RAZORPAY_KEY_ID', 'RAZORPAY_KEY_SECRET'],
    'Razorpay webhook verify (RAZORPAY_WEBHOOK_SECRET; else key secret is reused)': ['RAZORPAY_WEBHOOK_SECRET'],
    'Cloudinary uploads (CLOUDINARY_CLOUD_NAME, CLOUDINARY_API_KEY, CLOUDINARY_API_SECRET)': ['CLOUDINARY_CLOUD_NAME', 'CLOUDINARY_API_KEY', 'CLOUDINARY_API_SECRET'],
    'EmailJS notifications (EMAILJS_SERVICE_ID, EMAILJS_TEMPLATE_ID, EMAILJS_PUBLIC_KEY, EMAILJS_PRIVATE_KEY)': ['EMAILJS_SERVICE_ID', 'EMAILJS_TEMPLATE_ID', 'EMAILJS_PUBLIC_KEY', 'EMAILJS_PRIVATE_KEY'],
    'Phone OTP via Twilio (TWILIO_ACCOUNT_SID, TWILIO_AUTH_TOKEN, TWILIO_FROM_NUMBER)': ['TWILIO_ACCOUNT_SID', 'TWILIO_AUTH_TOKEN', 'TWILIO_FROM_NUMBER'],
    'Google Sign-In verify (GOOGLE_CLIENT_ID)': ['GOOGLE_CLIENT_ID'],
  };
  for (const [label, keys] of Object.entries(groups)) {
    const st = groupStatus(keys);
    if (!st.configured && st.missing.length !== keys.length && isProd) {
      warnings.push(`${label} is PARTIALLY configured (missing: ${st.missing.join(', ')}). The feature fails closed until complete.`);
    }
  }

  for (const w of warnings) console.warn(`[env] WARN: ${w}`);
  if (fatals.length) {
    for (const f of fatals) console.error(`[env] FATAL: ${f}`);
    throw new Error(`Missing required production environment: ${fatals.length} fatal issue(s). See [env] FATAL lines above (keys only, values never printed).`);
  }
  console.log(`[env] Environment check passed (NODE_ENV=${process.env.NODE_ENV || 'development'}).`);
}

/**
 * Persistent Fallback Storage
 *
 * PRODUCTION POLICY: Fallback storage is DISABLED in production. The app must
 * never silently serve demo/in-memory data or write to /tmp when Atlas is down.
 * API calls that need the DB will receive a 503 from the middleware in app.js.
 *
 * DEVELOPMENT: When MongoDB is unavailable locally, critical data is persisted
 * to JSON files so local work can proceed without Atlas.
 */

import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));

/**
 * Returns true when fallback/in-memory data stores should be used.
 * In production this is always false — the DB middleware returns 503 instead.
 */
export function isFallbackEnabled() {
  // In production, fallback storage is disabled by default.
  // Can only be enabled via explicit flag ENABLE_FALLBACK_STORAGE=true.
  if (process.env.NODE_ENV === 'production') {
    return process.env.ENABLE_FALLBACK_STORAGE === 'true';
  }
  return process.env.ENABLE_FALLBACK_STORAGE !== 'false';
}

function resolveFallbackDir() {
  // Production policy: NEVER resolve a fallback directory or write to /tmp in production
  if (process.env.NODE_ENV === 'production') return null;
  if (!isFallbackEnabled()) return null;

  if (process.env.FALLBACK_DIR) return process.env.FALLBACK_DIR;
  // In development on Vercel-like environments, use /tmp
  if (process.env.VERCEL || process.env.AWS_LAMBDA_FUNCTION_NAME) {
    return path.join('/tmp', 'sabr-studio-fallback');
  }
  const rootFallback = path.join(__dirname, '../../data/fallback');
  if (fs.existsSync(rootFallback)) return rootFallback;
  return path.join(__dirname, '../data/fallback');
}

let persistenceEnabled = process.env.NODE_ENV !== 'production' && isFallbackEnabled();
const fallbackDir = resolveFallbackDir();

if (fallbackDir && persistenceEnabled) {
  try {
    if (!fs.existsSync(fallbackDir)) {
      fs.mkdirSync(fallbackDir, { recursive: true });
    }
  } catch (err) {
    persistenceEnabled = false;
    console.error(
      `[FallbackStorage] Directory not writable (${fallbackDir}): ${err.message}. Running in in-memory mode.`
    );
  }
}

class FallbackStorage {
  constructor(collectionName) {
    this.collectionName = collectionName;
    this.filePath = fallbackDir ? path.join(fallbackDir, `${collectionName}.json`) : null;
    this.data = this._load();
  }

  _load() {
    if (!persistenceEnabled || !this.filePath || process.env.NODE_ENV === 'production') return [];
    try {
      if (fs.existsSync(this.filePath)) {
        return JSON.parse(fs.readFileSync(this.filePath, 'utf-8'));
      }
    } catch (err) {
      console.error(`[FallbackStorage:${this.collectionName}] Load error:`, err.message);
    }
    return [];
  }

  _save() {
    if (process.env.NODE_ENV === 'production' || !persistenceEnabled || !this.filePath) return false;
    try {
      fs.writeFileSync(this.filePath, JSON.stringify(this.data, null, 2), 'utf-8');
      return true;
    } catch (err) {
      console.error(`[FallbackStorage:${this.collectionName}] Save error:`, err.message);
      return false;
    }
  }

  findAll() {
    if (!isFallbackEnabled()) return [];
    return [...this.data];
  }

  findOne(query) {
    if (!isFallbackEnabled()) return null;
    if (query._id || query.id) {
      const id = query._id || query.id;
      return this.data.find(item => item._id === id || item.id === id) || null;
    }
    if (query.orderNumber) {
      return this.data.find(item => item.orderNumber === query.orderNumber) || null;
    }
    return null;
  }

  add(record) {
    if (!isFallbackEnabled()) return null;
    const generatedId = record._id || record.id || `fb-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
    const newRecord = {
      ...record,
      _id: record._id || generatedId,
      id: record.id || generatedId,
      createdAt: record.createdAt || new Date().toISOString(),
      updatedAt: new Date().toISOString(),
    };
    this.data.unshift(newRecord);
    this._save();
    return newRecord;
  }

  update(id, updates) {
    if (!isFallbackEnabled()) return null;
    const index = this.data.findIndex(item => item._id === id || item.id === id);
    if (index === -1) return null;
    this.data[index] = { ...this.data[index], ...updates, updatedAt: new Date().toISOString() };
    this._save();
    return this.data[index];
  }

  delete(id) {
    if (!isFallbackEnabled()) return false;
    const len = this.data.length;
    this.data = this.data.filter(item => item._id !== id && item.id !== id);
    if (this.data.length < len) {
      this._save();
      return true;
    }
    return false;
  }

  count() {
    if (!isFallbackEnabled()) return 0;
    return this.data.length;
  }

  clear() {
    if (!isFallbackEnabled()) return;
    this.data = [];
    this._save();
  }
}

export const fallbackOrders = new FallbackStorage('orders');
export const fallbackEnquiries = new FallbackStorage('enquiries');

export function hasFallbackData(collectionName) {
  if (!isFallbackEnabled() || !fallbackDir) return false;
  const filePath = path.join(fallbackDir, `${collectionName}.json`);
  return fs.existsSync(filePath) && fs.statSync(filePath).size > 0;
}

export function getFallbackCount(collectionName) {
  if (!isFallbackEnabled()) return 0;
  return new FallbackStorage(collectionName).count();
}

export function clearAllFallbackData() {
  if (!isFallbackEnabled() || !fallbackDir) return false;
  try {
    if (fs.existsSync(fallbackDir)) {
      fs.rmSync(fallbackDir, { recursive: true, force: true });
      fs.mkdirSync(fallbackDir, { recursive: true });
      console.log('[FallbackStorage] All data cleared');
      return true;
    }
  } catch (err) {
    console.error('[FallbackStorage] Clear error:', err.message);
  }
  return false;
}

export async function syncFallbackToMongoose({ orders = false, enquiries = false } = {}) {
  const result = { 
    orders: { synced: 0, failed: 0, skipped: 0 }, 
    enquiries: { synced: 0, failed: 0, skipped: 0 } 
  };
  
  try {
    if (orders) {
      const { Order } = await import('../models/order.model.js');
      for (const record of fallbackOrders.findAll()) {
        try {
          const existing = await Order.findOne({ 
            $or: [{ _id: record._id }, { orderNumber: record.orderNumber }] 
          });
          if (existing) { result.orders.skipped++; continue; }
          await Order.create(record);
          result.orders.synced++;
        } catch (err) {
          console.error('[FallbackSync] Order error:', err.message);
          result.orders.failed++;
        }
      }
    }

    if (enquiries) {
      const { Enquiry } = await import('../models/enquiry.model.js');
      for (const record of fallbackEnquiries.findAll()) {
        try {
          const existing = await Enquiry.findOne({ 
            $or: [{ _id: record._id }, { id: record.id }] 
          });
          if (existing) { result.enquiries.skipped++; continue; }
          await Enquiry.create(record);
          result.enquiries.synced++;
        } catch (err) {
          console.error('[FallbackSync] Enquiry error:', err.message);
          result.enquiries.failed++;
        }
      }
    }
  } catch (err) {
    console.error('[FallbackSync] Sync error:', err.message);
  }

  return result;
}

export default FallbackStorage;

// Development seed script – populates MongoDB with in‑memory seed data if collections are empty.
// This MUST NEVER run in production. Guarded by both NODE_ENV and isFallbackEnabled.

import { Project, inMemoryProjects } from '../models/project.model.js';
import { Retail, inMemoryRetail } from '../models/retail.model.js';
import { isFallbackEnabled } from '../utils/fallbackStorage.js';

export async function seedDevelopmentData() {
  if (process.env.NODE_ENV === 'production') return;
  if (!isFallbackEnabled()) return;

  // Helper to insert only when collection is empty
  const seedIfEmpty = async (Model, items, name) => {
    try {
      const count = await Model.countDocuments();
      if (count === 0 && Array.isArray(items) && items.length) {
        // Remove any existing inMemory IDs that might conflict with Mongo's ObjectId generation
        const docs = items.map((it) => {
          const { _id, id: _idAlias, ...rest } = it; // discard fake ids
          return rest;
        });
        await Model.insertMany(docs);
        console.log(`[seed] Inserted ${docs.length} ${name} records into MongoDB`);
      }
    } catch (e) {
      console.error(`[seed] Error seeding ${name}:`, e.message);
    }
  };

  await Promise.all([
    seedIfEmpty(Project, inMemoryProjects, 'projects'),
    seedIfEmpty(Retail, inMemoryRetail, 'retail'),
  ]);
}
